//! N8 conditionally-bounded bridge checks.
//!
//! The fixture is generated by `fock_sirk/examples/sm_defect_bridge.rs` and
//! binds the actual `finite_fixture` terms. Arithmetic endpoints are directed and
//! the spectral growth is Gershgorin-bounded, but the returned `G` and Padé flow
//! are not enclosed, so the overall status must stay `conditionally-bounded`.

use fock_sirk::sm_bridge::{BridgeError, bind_artifact, verify_bridge};
use fock_sirk::sm_defect::{
    CertificateHashes, Interval, finite_fixture, finite_fixture_bridge, verify_certificate,
};
use serde_json::{Value, json};

const FIXTURE: &str = include_str!("../../docs/fixtures/sm_defect_bridge.json");

#[test]
fn fixture_is_regenerated_from_the_actual_finite_fixture() {
    let pinned: Value = serde_json::from_str(FIXTURE).unwrap();
    let regenerated = finite_fixture_bridge(0.2);
    assert_eq!(pinned, regenerated, "regenerate with sm_defect_bridge");
    verify_bridge(&pinned).unwrap();

    assert_eq!(pinned["status"], "conditionally-bounded");
    assert_eq!(pinned["theorem"]["proof_status"], "not-run");
    assert_eq!(pinned["artifact"]["rounding"]["directed"], true);
    assert_eq!(
        pinned["artifact"]["rounding"]["spectral_growth_directed"],
        true
    );
    assert_eq!(
        pinned["artifact"]["rounding"]["spectral_input_enclosed"],
        false
    );
    assert_eq!(
        pinned["artifact"]["rounding"]["pade_exponential_directed"],
        false
    );
    assert_eq!(pinned["artifact"]["measured_within_interval_hi"], true);

    let (_, interval, measured) = finite_fixture(0.2);
    assert!(
        measured <= interval.evolution_bound.hi + 1e-12,
        "measured {measured:.6e} exceeds interval hi {:.6e}",
        interval.evolution_bound.hi
    );

    let certificate = &pinned["artifact"]["certificate"];
    let hashes = CertificateHashes {
        operator: certificate["hashes"]["operator"].as_str().unwrap().into(),
        state: certificate["hashes"]["state"].as_str().unwrap().into(),
        basis: certificate["hashes"]["basis"].as_str().unwrap().into(),
    };
    verify_certificate(certificate, &hashes).unwrap();
}

#[test]
fn interval_arithmetic_rounds_outward_and_keeps_zero_exact() {
    let (a, b) = (Interval::point(0.1), Interval::point(0.2));
    let sum = a.add(b);
    assert!(sum.lo <= 0.1 + 0.2 && sum.hi >= 0.1 + 0.2);

    let wide = Interval { lo: -0.3, hi: 0.7 };
    assert!(wide.square_upper() >= 0.49);

    let zero = Interval::point(0.0).add(Interval::point(0.0));
    assert_eq!(zero, Interval::point(0.0));
}

#[test]
fn bridge_rejects_mutation_and_uncertified_promotion() {
    let fixture: Value = serde_json::from_str(FIXTURE).unwrap();

    let mut mutated = fixture.clone();
    mutated["artifact"]["measured_map_error"] = json!(0.0);
    assert!(matches!(
        verify_bridge(&mutated),
        Err(BridgeError::ArtifactDigest { .. })
    ));

    let mut promoted = fixture.clone();
    promoted["status"] = json!("certified");
    let promoted = bind_artifact(promoted);
    assert_eq!(
        verify_bridge(&promoted).unwrap_err(),
        BridgeError::CertifiedWithoutProof
    );

    let mut rounding = fixture.clone();
    rounding["artifact"]["rounding"]["directed"] = json!(false);
    assert!(matches!(
        verify_bridge(&rounding),
        Err(BridgeError::ArtifactDigest { .. })
    ));
}
